}
q, e = parseQuotaMB("10 * 100")
if e != nil || q != 1048576000 {
	t.Fatalf("product quota %d %v", q, e)
}
life, e := parseLifetimeMinutes("5*60")
if e != nil || life != 18000 {
	t.Fatalf("life %d %v", life, e)

	}
