func TestOutputVisibleUntilTenSecondsBeforeExpiry(t *testing.T) {

	expiry := time.Date(2026, 9, 29, 12, 0, 0, 0, time.UTC)
	got := outputVisibleUntil(float64(expiry.UnixMilli()))
	want := expiry.Add(-10 * time.Second)
