func (s *Server) outputSnapshotResponse(w http.ResponseWriter, r *http.Request) {
	where := ` WHERE o.last_seen_at>=now()-interval '15 seconds' AND p.enabled=true AND d.state='PANEL_COMPLETE' AND a.provider_state<>'LOCKED' AND dr.state IN ('READY','EXPIRING','RETIRING') AND (dr.expires_at IS NULL OR dr.expires_at>now()+interval '10 seconds') AND (o.visible_until IS NULL OR o.visible_until>now()) `
	args := []any{}
	if raw := r.URL.Query().Get("expires_within_minutes"); raw != "" {
		n, e := strconv.Atoi(raw)

	if e != nil || n < 1 || n > 1440 {
		http.Error(w, "invalid expiry window", 400)
		return
	}
	args = append(args, n)
	where += ` AND dr.expires_at>now() AND dr.expires_at<=now()+($1*interval '1 minute') `
}
if raw := r.URL.Query().Get("created_within_minutes"); raw != "" {

	n, e := strconv.Atoi(raw)
	if e != nil || n < 1 || n > 1440 {
		http.Error(w, "invalid created window", 400)
		return
	}
	args = append(args, n)
	where += ` AND o.first_seen_at>=now()-($` + strconv.Itoa(len(args)) + `*interval '1 minute') `
}

for rows.Next() {
	var u string
	if rows.Scan(&u) == nil {
		out.WriteString(u)
		out.WriteByte('\n')
	}
}
w.Header().Set("Content-Type", "text/plain; charset=utf-8")

	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(out.String()))
}

