func normalizeProxyPool(primary string, ids []string) []string {

seen := map[string]bool{}
out := make([]string, 0, len(ids)+1)
if primary != "" {
	out = append(out, primary)
	seen[primary] = true
}
for _, id := range ids {
	if id != "" && !seen[id] {

			seen[id] = true
			out = append(out, id)
		}
	}
	return out
}
