func (c Container) ensureActiveAccountProxy(ctx context.Context, accountID string) error {
	var mode, active string
	if err := c.DB.QueryRowContext(ctx, `SELECT mode,COALESCE(proxy_id::text,'') FROM network_profiles WHERE account_id=$1`, accountID).Scan(&mode, &active); err != nil {
		return err
	}
	if mode != "proxy_required" {
		return nil
	}

var usable bool
if active != "" {
	_ = c.DB.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM account_proxy_pool ap JOIN proxies p ON p.id=ap.proxy_id WHERE ap.account_id=$1 AND ap.proxy_id=$2::uuid AND ap.enabled=true AND p.status='healthy')`, accountID, active).Scan(&usable)
}
if usable {
	return nil
}
var next string

err := c.DB.QueryRowContext(ctx, `SELECT p.id::text FROM account_proxy_pool ap JOIN proxies p ON p.id=ap.proxy_id WHERE ap.account_id=$1 AND ap.enabled=true AND p.status='healthy' ORDER BY ap.priority,ap.proxy_id LIMIT 1`, accountID).Scan(&next)
if errors.Is(err, sql.ErrNoRows) {
	return ErrNetworkNotReady
}
if err != nil {
	return err
}
tx, err := c.DB.BeginTx(ctx, nil)

if err != nil {
	return err
}
defer tx.Rollback()
if _, err = tx.ExecContext(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, "account-proxy:"+accountID); err != nil {
	return err
}
var current string

if err = tx.QueryRowContext(ctx, `SELECT COALESCE(proxy_id::text,'') FROM network_profiles WHERE account_id=$1 FOR UPDATE`, accountID).Scan(&current); err != nil {
	return err
}
if current != next {
	if _, err = tx.ExecContext(ctx, `UPDATE network_profiles SET proxy_id=$2::uuid,updated_at=now() WHERE account_id=$1`, accountID, next); err != nil {
		return err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO account_network_identities(account_id,timezone,locale,last_health_ok,updated_at) VALUES($1,'UTC','en-US',false,now()) ON CONFLICT(account_id) DO UPDATE SET sticky_session=NULL,fallback_active=false,rotation_started_at=NULL,exit_ip=NULL,subnet_key=NULL,asn=NULL,country=NULL,last_health_ok=false,last_health_at=NULL,updated_at=now()`, accountID); err != nil {

			return err
		}
	}
	return tx.Commit()
}

package app

import "strings"

type ProxyCapabilities struct{ CountryTargeting, StickySession, SessionTTL bool }
type ProxySessionRequest struct {
	BaseUsername, CountryCode, SessionID string
	TargetCountry                        bool

}
type ProxyProviderAdapter interface {
	Name() string
	Match(string) bool
	Capabilities() ProxyCapabilities
	Username(ProxySessionRequest) string
}

type genericProxyAdapter struct{}

func (genericProxyAdapter) Name() string                          { return "generic" }
func (genericProxyAdapter) Match(string) bool                     { return true }
func (genericProxyAdapter) Capabilities() ProxyCapabilities       { return ProxyCapabilities{} }
func (genericProxyAdapter) Username(r ProxySessionRequest) string { return r.BaseUsername }

type suffixSessionAdapter struct{}

func (suffixSessionAdapter) Name() string { return "suffix-session" }
func (suffixSessionAdapter) Match(base string) bool {
	return strings.Contains(base, "__") || strings.Contains(base, "sid.") || strings.Contains(base, "cr.")
}
func (suffixSessionAdapter) Capabilities() ProxyCapabilities {
	return ProxyCapabilities{CountryTargeting: true, StickySession: true, SessionTTL: true}
}

func (suffixSessionAdapter) Username(r ProxySessionRequest) string {
	base := r.BaseUsername
	if i := strings.Index(base, "__"); i >= 0 {
		base = base[:i]
	}
	p := []string{}
	if r.TargetCountry && r.CountryCode != "" {
		p = append(p, "cr."+strings.ToLower(r.CountryCode))

}
if r.SessionID != "" {
	p = append(p, "sid."+r.SessionID)
}
if len(p) == 0 {
	return base
}
return base + "__" + strings.Join(p, ";")

}

func proxyAdapterByName(name string) ProxyProviderAdapter {
	switch strings.ToLower(strings.TrimSpace(name)) {
	case "suffix-session":
		return suffixSessionAdapter{}
	default:
		return genericProxyAdapter{}

	}
}
func proxySessionUsername(adapter, base, country, session string, targeted bool) string {
	return proxyAdapterByName(adapter).Username(ProxySessionRequest{BaseUsername: base, CountryCode: country, SessionID: session, TargetCountry: targeted})
}

// ProxySessionUsername exposes the canonical adapter rewrite for preview/validation paths.
func ProxySessionUsername(adapter, base, country, session string, targeted bool) string {

	return proxySessionUsername(adapter, base, country, session, targeted)
}

func ProxyAdapterCapabilities(adapter string) ProxyCapabilities {
	return proxyAdapterByName(adapter).Capabilities()
}

