func (d Driver) probe(ctx context.Context, in panels.Instance, method, path string) (int, error) {
	base := strings.TrimRight(in.BaseURL, "/") + "/"

req, err := http.NewRequestWithContext(ctx, method, base+strings.TrimLeft(path, "/"), nil)
if err != nil {
	return 0, err
}
