	}

	form := url.Values{}

if targets != "" {
	form.Set("targets", targets)
}

resp, err := exec.Do(ctx, SessionRequest{
	Method:         http.MethodPost,
	Path:           "panel/api/server/scanRealityTargets",
	Body:           []byte(form.Encode()),

	ContentType:    "application/x-www-form-urlencoded",
