func Build(
	input Input,
) (Payload, error) {

	if input.Remark == "" ||
		input.Port < 1 ||
		input.Port > 65535 ||
		input.UUID == "" ||

	input.Target == "" ||
	(input.ServerName == "" && len(input.ServerNames) == 0) ||
	input.PrivateKey == "" ||
	input.ShortID == "" {

	return Payload{},
		ErrInvalidConfig
}

if len(input.ServerNames) == 0 {
	input.ServerNames = []string{input.ServerName}
}
if input.ServerName == "" {
	input.ServerName = input.ServerNames[0]
}
if strings.ContainsAny(input.Target, "/\\ \t\r\n") {

	return Payload{}, ErrInvalidConfig
}
for _, name := range input.ServerNames {
	if name == "" || strings.ContainsAny(name, "/\\ \t\r\n") {
		return Payload{}, ErrInvalidConfig
	}
}

if input.TargetPort == 0 {
	input.TargetPort = 443
}
if input.TargetPort < 1 || input.TargetPort > 65535 {
	return Payload{}, ErrInvalidConfig
}

if input.Fingerprint == "" {

	input.Fingerprint = "chrome"
}

if input.Flow == "" {
	input.Flow =
		"xtls-rprx-vision"
}

settings :=
	map[string]any{
		"clients": []any{
			map[string]any{
				"id": input.UUID,

				"email": input.Email,

		"flow": input.Flow,

		"enable": true,
	},
},

"decryption": "none",

		"encryption": "none",

		"fallbacks": []any{},
	}

realitySettings :=
	map[string]any{
		"show": false,

"serverNames": input.ServerNames,

"privateKey": input.PrivateKey,

"shortIds": []string{
	input.ShortID,
},

		"fingerprint": input.Fingerprint,
	}

streamSettings :=
	map[string]any{
		"network": "tcp",

		"security": "reality",

		"realitySettings": realitySettings,
	}

sniffing :=
	map[string]any{
		"enabled": true,

"destOverride": []string{
	"http",
	"tls",
	"quic",
},

"metadataOnly": false,

		"routeOnly": false,
	}

return Payload{
	Enable: true,

	Remark: input.Remark,

	}, nil
}

func Marshal(
	input Input,
) ([]byte, error) {

	payload, err :=

	Build(
		input,
	)

if err != nil {
	return nil, err
}

	return json.Marshal(
		payload,
	)
}

