	return r, nil
}
if err != nil {
	return r, err
}
r.Stable = true

r.Switched = sw
r.Selected = choice.Candidate.Target
if current == nil || sw {
	score := Score{Candidate: choice.Candidate, Eligible: true, MedianLatencyMS: choice.MedianLatencyMS, SuccessRatio: choice.SuccessRatio, Value: choice.Score, Reason: "stable"}
