var ErrCircuitOpen = errors.New("circuit breaker open")

type CircuitState string

const (
	Closed   CircuitState = "closed"
	Open     CircuitState = "open"
	HalfOpen CircuitState = "half_open"

}

func (c *Circuit) Allow(now time.Time) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.State == "" {
		c.State = Closed
	}

if c.State == Open {
	if now.Sub(c.OpenedAt) >= c.Policy.OpenDuration {
		c.State = HalfOpen
		return nil
	}
	return ErrCircuitOpen
}
return nil

}
func (c *Circuit) Success() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.State = Closed
	c.Failures = 0
	c.OpenedAt = time.Time{}
}

func (c *Circuit) Failure(now time.Time) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.Failures++
	threshold := c.Policy.FailureThreshold
	if threshold < 1 {
		threshold = 5
	}

	if c.Failures >= threshold || c.State == HalfOpen {
		c.State = Open
		c.OpenedAt = now
	}
}

	FailureThreshold int
	OpenDuration     time.Duration
}

func DefaultPolicy() Policy {
	return Policy{BaseDelay: time.Second, MaxDelay: 30 * time.Second, MaxAttempts: 5, FailureThreshold: 5, OpenDuration: time.Minute}
}
func (p Policy) Delay(attempt int) time.Duration {

if attempt < 1 {
	attempt = 1
}
d := p.BaseDelay
if d <= 0 {
	d = time.Second
}
max := p.MaxDelay

if max <= 0 {
	max = 30 * time.Second
}
for i := 1; i < attempt && d < max; i++ {
	d *= 2
	if d > max {
		d = max
	}

	}
	return d
}

type ErrorClass string

const (
	Retryable   ErrorClass = "retryable"

package resilience

import (
	"context"
	"time"
)

type Classifier func(error) ErrorClass

type Retrier struct {
	Policy   Policy
	Circuit  *Circuit
	Classify Classifier
}

func (r Retrier) Do(ctx context.Context, fn func() error) error {
	p := r.Policy

if p.MaxAttempts < 1 {
	p = DefaultPolicy()
}
for attempt := 1; attempt <= p.MaxAttempts; attempt++ {
	if r.Circuit != nil {
		if err := r.Circuit.Allow(time.Now()); err != nil {
			return err
		}

}
err := fn()
if err == nil {
	if r.Circuit != nil {
		r.Circuit.Success()
	}
	return nil
}

class := Unknown
if r.Classify != nil {
	class = r.Classify(err)
}
if class == Permanent {
	return err
}
if r.Circuit != nil {

	r.Circuit.Failure(time.Now())
}
if attempt == p.MaxAttempts {
	return err
}
delay := p.Delay(attempt)
select {
case <-ctx.Done():

			return ctx.Err()
		case <-time.After(delay):
		}
	}
	return nil
}

